import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../services/erp_workspace_records_service.dart';
import '../widgets/erp_quick_task_button.dart';

class ErpItemUnitsScreen extends StatefulWidget {
 const ErpItemUnitsScreen({super.key,this.companyId}); final String? companyId;
 @override State<ErpItemUnitsScreen> createState()=>_ErpItemUnitsScreenState();
}
class _ErpItemUnitsScreenState extends State<ErpItemUnitsScreen>{
 final service=ErpWorkspaceRecordsService(); List<Map<String,String>> rows=[]; List<String> activities=[]; String activity=''; String? company; String? message; bool loading=false,saving=false;
 static const page='وحدات الأصناف';
 @override void initState(){super.initState();load();}
 Future<void> load()async{setState(()=>loading=true);try{final db=Supabase.instance.client;var c=(widget.companyId??'').trim();final uid=db.auth.currentUser?.id;if(uid!=null){final m=await db.from('erp_company_members').select('company_id').eq('user_id',uid).eq('is_active',true).order('created_at');final ids=(m as List).map((x)=>(x['company_id']??'').toString()).toList();if(c.isEmpty||!ids.contains(c)){c=ids.isEmpty?'':ids.first;}}if(c.isEmpty)throw StateError('لا توجد شركة نشطة.');final a=await db.from('activity_types').select('name').eq('is_active',true).order('sort_order');final r=await service.listPage(companyId:c,pageKey:page);if(!mounted)return;setState(()=>{company=c,activities=(a as List).map((x)=>(x['name']??'').toString()).where((x)=>x.isNotEmpty).toList(),rows=r,activity=activity.isNotEmpty?activity:((a as List).isEmpty?'':(a as List).first['name'].toString()),loading=false,message=null});}catch(e){if(mounted)setState(()=>{loading=false,message='تعذر تحميل وحدات الأصناف: $e'});}}
 void add(){setState(()=>rows.add({'م':'${rows.length+1}','كود الوحدة':'','اسم الوحدة عربي':'','اسم الوحدة إنجليزي':'','نوع النشاط':activity,'نشط':'true','_مسودة':'true'}));}
 Future<void> save()async{if(company==null)return;setState(()=>saving=true);try{for(final r in rows.where((r)=>(r['نوع النشاط']??'')==activity)){if((r['كود الوحدة']??'').trim().isEmpty||(r['اسم الوحدة عربي']??'').trim().isEmpty)continue;final p=Map<String,String>.from(r)..remove('_مسودة');await service.saveRecord(companyId:company!,pageKey:page,record:p);}await load();if(mounted)setState(()=>message='تم حفظ وحدات النشاط في قاعدة البيانات.');}catch(e){if(mounted)setState(()=>message='تعذر الحفظ: $e');}finally{if(mounted)setState(()=>saving=false);}}
 Future<void> remove(Map<String,String> r)async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('حذف الوحدة'),content:Text('حذف «${r['اسم الوحدة عربي']??''}»؟'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(style:FilledButton.styleFrom(backgroundColor:Colors.red),onPressed:()=>Navigator.pop(c,true),child:const Text('حذف'))]));if(yes!=true)return;try{final key=r['_مرجع داخلي']??r['كود الوحدة']??'';if(key.isNotEmpty)await service.deleteRecord(companyId:company!,pageKey:page,recordKey:key);setState(()=>rows.remove(r));}catch(e){setState(()=>message='تعذر الحذف: $e');}}
 Widget task(String t,IconData i,Color c,VoidCallback? f)=>ErpQuickTaskButton(label:t,icon:i,onPressed:f,fallbackColor:c);
 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
 Card(color:const Color(0xFF3E007D),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('وحدات الأصناف',style:TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),DropdownButtonFormField<String>(value:activities.contains(activity)?activity:null,decoration:const InputDecoration(labelText:'نوع النشاط'),items:activities.map((a)=>DropdownMenuItem(value:a,child:Text(a))).toList(),onChanged:(v)=>setState(()=>activity=v??'')),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[task('تحديث',Icons.refresh,Colors.blue,loading?null:load),task('إضافة',Icons.add,Colors.green,add),task('حفظ',Icons.save,const Color(0xFF3E007D),saving?null:save)]))]))),
 if(message!=null)Padding(padding:const EdgeInsets.all(8),child:Text(message!)),if(loading)const LinearProgressIndicator(),
 Expanded(child:SingleChildScrollView(scrollDirection:Axis.horizontal,child:SingleChildScrollView(child:DataTable(columns:const [DataColumn(label:Text('م')),DataColumn(label:Text('كود الوحدة')),DataColumn(label:Text('اسم الوحدة عربي')),DataColumn(label:Text('اسم الوحدة إنجليزي')),DataColumn(label:Text('نشط')),DataColumn(label:Text('حذف'))],rows:rows.where((r)=>(r['نوع النشاط']??'')==activity).toList().asMap().entries.map((e){final r=e.value;return DataRow(cells:[DataCell(Text('${e.key+1}')),DataCell(SizedBox(width:120,child:TextFormField(initialValue:r['كود الوحدة'],onChanged:(v)=>r['كود الوحدة']=v,decoration:const InputDecoration(isDense:true)))),DataCell(SizedBox(width:180,child:TextFormField(initialValue:r['اسم الوحدة عربي'],onChanged:(v)=>r['اسم الوحدة عربي']=v,decoration:const InputDecoration(isDense:true)))),DataCell(SizedBox(width:180,child:TextFormField(initialValue:r['اسم الوحدة إنجليزي'],onChanged:(v)=>r['اسم الوحدة إنجليزي']=v,decoration:const InputDecoration(isDense:true)))),DataCell(Checkbox(value:(r['نشط']??'true')!='false',onChanged:(v)=>setState(()=>r['نشط']=(v??false).toString()))),DataCell(IconButton(onPressed:()=>remove(r),icon:const Icon(Icons.delete_forever,color:Colors.red)))]);} ).toList()))))
 ]));
}
